-- Official SAT Practice Tests (paper versions), generated by supabase/content/sat/build_sat.py. Do not edit by hand.
-- Run after migration 20261121000001_student_produced_responses.sql. Safe to re-run: existing exams are skipped.

select s.id, 'topic', v.name, v.ord from (values
  ('sat-math', 'Algebra', 1),
  ('sat-math', 'Advanced Math', 2),
  ('sat-math', 'Problem-Solving and Data Analysis', 3),
  ('sat-math', 'Geometry and Trigonometry', 4),
  ('sat-english', 'Craft and Structure', 1),
  ('sat-english', 'Information and Ideas', 2),
  ('sat-english', 'Standard English Conventions', 3),
  ('sat-english', 'Expression of Ideas', 4)
) as v(code, name, ord) join public.subjects s on s.code = v.code
on conflict (subject_id, kind, name) do nothing;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 9: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-9-reading-and-writing') then
    raise notice 'skipping sat-practice-test-9-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-9-reading-and-writing', 'SAT Practice Test 9: Reading and Writing', 'Official SAT Practice Test 9 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 218, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [210, 250], [220, 260], [220, 270], [230, 280], [230, 290], [240, 300], [250, 310], [260, 320], [270, 330], [280, 340], [300, 340], [310, 350], [320, 360], [330, 370], [330, 370], [340, 380], [350, 390], [360, 400], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 530], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [620, 680], [630, 690], [660, 700], [670, 710], [680, 720], [690, 730], [710, 750], [720, 760], [730, 770], [740, 780], [760, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “arranged” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because as used in the text, “arranged” most nearly means “organized.” The text states that a welcome feature of Manchester’s art galleries (as opposed to others) is that the titles of the paintings are easy to see and that a catalogue is therefore unneeded while visitors browse the art galleries. This suggests that the paintings are displayed in a systematic, or organized, way."}, {"type": "paragraph", "text": "Choice B is incorrect. “Ranked” might mean either classified or placed in orderly rows. Neither of these meanings would necessarily imply that the names of the paintings are easy to see (even if the paintings are placed in rows, their labels might be obscured). Choice C is incorrect because it would not make sense in context to describe the paintings as “scheduled,” or planned to take place at a certain time. Choice D is incorrect because if the paintings were “discussed,” or talked about, this would have no bearing on whether the names of the paintings could be easily seen."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the challenge of generating electricity from ocean waves. In this context, “consistent” means steady or unchanging over time. The text introduces a challenge and then explains that wave power varies, or changes, unpredictably in ways that cause problems for electricity generation. This context conveys that the challenge being described is a lack of consistency."}, {"type": "paragraph", "text": "Choice A is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn’t indicate that wave power isn’t “accidental,” or isn’t happening unintentionally. It wouldn’t make sense to describe waves—a natural occurrence—as happening intentionally. Choice B is incorrect because “confident” means having a feeling of self-assurance, and it wouldn’t make sense to describe wave power itself in terms of either having or lacking a sense of confidence. Choice C is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn’t indicate that wave power isn’t “expensive,” or isn’t costly. If anything, technological and planning problems might actually increase the expense of generating electricity from waves."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of John Ashbery’s poems. As used in this context, “interpret” would mean decipher the meaning of. The text indicates that Ashbery’s poems have many unusual features, that it’s difficult to tell what exactly the poems’ subject matter is, and that scholars strongly disagree about the poems. This context conveys the idea that it’s difficult to interpret Ashbery’s poems."}, {"type": "paragraph", "text": "Choice A is incorrect because “delegate” means to assign someone as a representative of another person or to entrust something to someone else, neither of which would make sense in context. The text is focused only on the difficulty that readers have interpreting Ashbery’s poems due to their many unusual features; it doesn’t suggest anything about the poems being difficult to delegate. Choice B is incorrect because describing Ashbery’s poems as difficult to “compose,” or put together or produce, would make sense only if the text were about Ashbery’s experience of writing the poems. It could be true that it was difficult for Ashbery to compose his poems, but the text doesn’t address this; it instead discusses how readers interpret and engage with the poems. Choice D is incorrect because describing Ashbery’s poems as being difficult to “renounce,” or give up or refuse, wouldn’t make sense in context. The text focuses on the idea that features of Ashbery’s poems are odd or unclear and have caused heated scholarly debate. This context suggests that the poems are difficult to interpret, not that the poems are difficult to renounce."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the discussion of the artist Diego Velázquez’s influence outside Spain. As used in this context, “confined to” means restricted to. The text says that Velázquez was the leading artist in the Spanish court during the seventeenth century, but it also notes that other painters around the world were influenced by his techniques and style. Thus, Velázquez’s influence was hardly (or almost not) confined to, or restricted to, Spain."}, {"type": "paragraph", "text": "Choice A is incorrect because if Velázquez was a leading artist in Spain, it doesn’t make logical sense to claim that his influence was hardly (or almost not) derived from, or obtained from, Spain. Moreover, the other painters around the world who employed Velázquez’s techniques would by definition be influenced by Spanish style. Choice B is incorrect because if Velázquez was a leading artist in the court of King Philip IV of Spain, then his influence must have been widely recognized, or acknowledged, rather than being hardly (or almost not) recognized. Choice D is incorrect because the text gives no indication that deliberately limiting Velázquez’s influence outside Spain was ever considered by anyone. Thus, even if it is true that his influence was not repressed, or restrained, it doesn’t make logical sense to say so in this context."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the discussion of Octavia Butler’s career. In this context, “impenetrable” means impossible to enter. The text indicates that the field of science fiction was dominated by white males when Butler, a Black woman, started writing, but she published several science fiction short stories and a novel and later won a prestigious award; that is, Butler pursued science fiction writing and had success. This context suggests that Butler didn’t view the genre as impossible to enter."}, {"type": "paragraph", "text": "Choice A is incorrect. In this context, “legitimate” would mean genuinely good or valid. Nothing in the text suggests that Butler didn’t think the science fiction genre was good or valid; in fact, it indicates that she pursued and made a successful career of publishing work in that field. Choice C is incorrect. In this context, “compelling” would mean attracting or demanding attention. The text indicates that Butler chose to write science fiction, so it wouldn’t make sense to say that she didn’t see the field as drawing her attention. Choice D is incorrect. To say that Butler didn’t consider science fiction “indecipherable,” or impossible to understand, would suggest that Butler did understand it. However, the text doesn’t address Butler’s ability to interpret works in the genre; rather, it focuses on Butler’s successful pursuit of writing science fiction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The underlined sentence establishes a difference between Uncle Katsuhisa and the narrator’s father by describing Uncle Katsuhisa as “loud” and the narrator’s father as “quiet.” The text then elaborates on that contrast, describing some ways Uncle Katsuhisa is very noisy even when he isn’t speaking."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate what kinds of topics Uncle Katsuhisa enjoys discussing, only that he is loud even when he isn’t speaking."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never indicates how Uncle Katsuhisa feels about meeting new people, only how loud he is. Choice D is incorrect because the text never describes a conversation occurring between any people; it refers to talking only when stating that Uncle Katsuhisa is loud even when he isn’t speaking."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it best describes how the underlined sentence functions in the text as a whole. According to the text, it was hard for Yamauchi to adapt her short story into the play And the Soul Shall Dance because the story had included little dialogue, instead describing the characters’ silent thoughts. The underlined sentence offers information about how Yamauchi ultimately succeeded in adapting the story into a play: it explains that Yamauchi created situations where the characters of the play could reveal their internal thoughts while speaking with each other."}, {"type": "paragraph", "text": "Choice B is incorrect because neither the underlined sentence nor the text as a whole makes any mention of playwrights other than Yamauchi or how the play might have influenced them. Choice C is incorrect because the text states that Yamauchi is best known for her play And the Soul Shall Dance, which conveys that the play is better known than the short story it’s based on is. Choice D is incorrect because neither the underlined sentence nor the text as a whole mentions the actors who performed in the play or Yamauchi’s approach to choosing them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the function of the underlined portion in the text as a whole. The text establishes that many countries have adopted risk-disclosure requirements for financial products due to concerns that consumers don’t understand the risks associated with the products. According to the text, Seira et al. found that the effects of such messaging on consumer behavior were small and temporary. The text then adds that the researchers assert that because the cost of the messaging is negligible, the approach may be worth doing even if the effects are limited. Thus, the underlined portion notes a factor—very low cost—that led the researchers to not completely dismiss risk-disclosure messaging despite their evidence of its limited utility."}, {"type": "paragraph", "text": "Choice B is incorrect because the underlined portion doesn’t refer to a particular type of risk-disclosure messaging, whether Seira et al. considered it or not; the underlined portion simply indicates that the cost of the messaging (broadly) is very low, which makes the approach worth pursuing even if its effects are limited."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the underlined portion does describe a consideration that led the researchers to recommend risk-disclosure messaging despite the messaging’s small effects on consumer behavior, it directly states that the cost of such messaging is negligible, or very low—meaning that both the effects and the costs are small, not that the effects are small only relative to the costs. Choice D is incorrect because there’s no indication that Seira et al. suggest that risk-disclosure messaging could be more effective if it had lower costs; rather, the underlined portion indicates that Seira et al. believe the already negligible cost of messaging makes the approach worth pursuing even if its effects are limited."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Focarelli and Panetta (Text 2) most likely respond to Fan’s findings (Text 1)?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because, based on the information presented in the texts, it represents how Focarelli and Panetta would most likely respond to Fan’s findings. Text 1 indicates that Fan found that a newspaper merger would result in a rise in subscription prices. This rise wouldn’t benefit customers, who would have to pay more for news after a merger. Text 2 presents Focarelli and Panetta’s argument that merger research tends to focus too much on what happens immediately after the merger. Text 2 goes on to describe their finding that mergers can be economically beneficial for consumers over the long term. This suggests that Focarelli and Panetta would encourage Fan to investigate the long-term effect of the hypothetical newspaper merger on subscription prices."}, {"type": "paragraph", "text": "Choice A is incorrect because Text 2 doesn’t indicate that Focarelli and Panetta connect the effects of mergers to specific locations. Instead, Focarelli and Panetta focus on the length of time over which the effects of mergers should be evaluated. Choice B is incorrect because Text 2 indicates that Focarelli and Panetta found that merged companies experience “efficiency gains” over the long term, meaning that their expenses go down relative to their output, not that their expenses increase. Choice D is incorrect because there’s no indication in Text 2 that Focarelli and Panetta believe that the newspaper industry is different from any other industry when it comes to the effects of mergers. Although their own research was about consumer banking, Text 2 suggests that they view their conclusions as applicable to mergers in general."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, why are ecologists worried about Pando?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents an explanation that is directly stated in the text for why ecologists are worried about Pando. The text states that Pando is a colony of about 47,000 quaking aspen trees that represents one of the largest organisms on Earth. According to the text, ecologists are worried that Pando’s growth is declining, partly because animals are feeding on the trees. In other words, the ecologists are worried that Pando isn’t growing at the same rate it used to."}, {"type": "paragraph", "text": "Choice B is incorrect. Rather than indicating that Pando isn’t producing young trees anymore, the text reveals that Pando is indeed producing young trees, stating that those trees can be protected from grazing deer by strong fences."}, {"type": "paragraph", "text": "Choice C is incorrect because the text states that fences can be used to prevent deer from eating Pando’s young trees, not that Pando itself can’t grow in new areas because it’s blocked by fences. Choice D is incorrect because the text offers no evidence that Pando’s root system is incapable of supporting new trees or is otherwise a cause of worry for ecologists."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the table, in which year was the dolphin with the ID FB43 recorded with her calf?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately reflects the data in the table. According to the table, the dolphin with ID FB43 has a recording year of 1992."}, {"type": "paragraph", "text": "Choice A is incorrect. None of the dolphins in the table have a recording year of 1999. Choice B is incorrect. The table shows 2012 as the recording year for the dolphin with ID FB07, not ID FB43. Choice C is incorrect. None of the dolphins in the table have a recording year of 2020."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most effectively uses data from the table to complete the statement about the forestry student’s project. The table shows five types of maple trees, each tree’s maximum height, and whether each tree is native to North America. The text indicates that the student needs to recommend a maple tree that’s native to North America and won’t reach a height greater than 60 feet. The red maple is the only tree listed in the table that meets these criteria: its maximum height is 60 feet—meaning that it won’t grow higher than 60 feet— and it’s native to North America."}, {"type": "paragraph", "text": "Choice A is incorrect because the text states that the student needs to recommend a tree that’s native to North America and won’t grow higher than 60 feet, but the table shows that the maximum height of the silver maple is 70 feet. Choice B is incorrect because the text states that the student needs to recommend a tree that’s native to North America and won’t grow higher than 60 feet, but the table shows that the maximum height of the sugar maple is 75 feet. Choice D is incorrect because the text states that the student needs to recommend a tree that’s native to North America and won’t grow higher than 60 feet, but the table shows that the Norway maple isn’t native to North America."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data in the graph that support Ayalew and her colleagues’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it best describes data in the graph supporting Ayalew and her colleagues’ hypothesis that plants’ response to kanamycin exposure involves altering their uptake of metals. The graph compares the metal content of two groups of plants, one with kanamycin exposure and a control group without such exposure. The amount of zinc in plants without kanamycin exposure is around 400 parts per million, while the amount of zinc in plants with kanamycin exposure is lower, at around 300 parts per million. Similarly, the amount of iron in plants without kanamycin exposure is a little over 600 parts per million, while the amount of iron in plants with kanamycin exposure is lower, at a little over 200 parts per million. Thus, the graph shows that plants with kanamycin exposure have significantly lower levels of both iron and zinc than the plants without kanamycin exposure. This is evidence supporting the hypothesis that kanamycin exposure results in plants altering their uptake of metals."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph shows that control plants contained higher levels of iron than zinc, not higher levels of zinc than iron; similarly, the plants exposed to kanamycin contained higher levels of zinc than iron, not higher levels of iron than zinc. Choice B is incorrect. Though the claim that both groups of plants contained more than 200 parts per million of both iron and zinc is supported by the graph, this alone does not state whether plants with kanamycin exposure have a different metal content than plants without kanamycin exposure."}, {"type": "paragraph", "text": "Choice C is incorrect. The graph shows that the zinc levels for the control plants (those without kanamycin exposure) were around 400 parts per million, not 300 parts per million, and that the zinc levels for plants with kanamycin exposure were around 300 parts per million, not 400 parts per million."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the table that support the researcher’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it describes data from the table that support the researcher’s hypothesis. According to the text, the researcher hypothesized that Arctic ground squirrels would exhibit longer torpor bouts and shorter arousal episodes than Alaska marmots do—or, put the other way, that the marmots would show shorter torpor bouts and longer arousal episodes than the ground squirrels do. The table shows data about torpor bouts and arousal episodes for the two species from 2008 to 2011. According to the table, the average duration of torpor bouts was 13.81 days for Alaska marmots, shorter than the average of 16.77 days for Arctic ground squirrels, and the average duration of arousal episodes was 21.2 hours for Alaska marmots, longer than the average of 14.2 hours for Arctic ground squirrels. Thus, the table supports the researcher’s hypothesis by showing that Alaska marmots had shorter bouts of torpor and longer arousal episodes than Arctic ground squirrels did."}, {"type": "paragraph", "text": "Choice A is incorrect because it inaccurately describes data from the table and doesn’t support the researcher’s hypothesis. The table shows that the average duration of arousal episodes was less than a day for both Alaska marmots (21.2 hours) and Arctic ground squirrels (14.2 hours). Additionally, information about arousal episodes for Alaska marmots and Arctic ground squirrels isn’t sufficient to support a hypothesis involving comparisons of both arousal episodes and torpor bouts for those animals. Choice B is incorrect because it doesn’t support the researcher’s hypothesis, which involves comparisons of arousal episodes as well as torpor bouts for Alaska marmots and Arctic ground squirrels. Noting that both animals had torpor bouts lasting several days, on average, doesn’t address arousal episodes at all, nor does it reveal how the animals’ torpor bouts compared. Choice D is incorrect because it doesn’t support the researcher’s hypothesis. Although the table does show that Alaska marmots had more torpor bouts (12) than arousal episodes (11) and that their arousal episodes were much shorter than their torpor bouts (21.2 hours and 13.81 days, respectively), comparing data across only Alaska marmot behaviors isn’t sufficient to support a hypothesis about torpor and arousal behaviors of both Alaska marmots and Arctic ground squirrels."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the student’s conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the graph to complete the student’s conclusion about beehive structure. The text explains that in the hives of honeybees, the hexagonal cells housing drone eggs are larger than the hexagonal cells housing worker eggs, and that this size difference results in a construction problem that the bees address by using nonhexagonal cells to fill gaps between sections of drone-egg cells and worker-egg cells. The text also states that the size difference between drone-egg cells and worker-egg cells varies by species of honeybee. The graph displays data on the percentage of nonhexagonal cells in the hives of three species. In the hives of the western honeybee, the percentages of five-sided, seven-sided, and eight-sided cells are all less than 0.5%. But in the hives of the black dwarf honeybee, the percentages of five-sided and seven-sided cells are higher than those for the western honeybee: about 2.5% for both. And for the dwarf honeybee, the percentages of five-sided and seven-sided cells are also higher than those for the western honeybee: slightly over 2.5% and slightly over 2.0%, respectively; additionally, the dwarf honeybee possesses a higher percentage of eight-sided cells than the western honeybee does. Taken altogether, the graph shows that the hives of the western honeybee consist of a smaller percentage of nonhexagonal cells than the hives of the two other species do. Since the nonhexagonal cells exist only to solve the construction problem arising from the difference in size between drone-egg cells and worker-egg cells, a smaller percentage of nonhexagonal cells would be associated with a smaller size difference between the two types of cells. Therefore, it can be concluded from the data that worker-egg cells are probably closer in size to drone-egg cells in the hives of the western honeybee than in the hives of the other two species."}, {"type": "paragraph", "text": "Choice B is incorrect because, as the text states, honeybee species deposit their eggs in hexagonal cells, not in nonhexagonal ones. Thus, the western honeybee and black dwarf honeybee wouldn’t deposit drone eggs in eight-sided cells, and the dwarf honeybee wouldn’t deposit drone eggs in seven-sided cells. Choice C is incorrect. The text explains that honeybees rely mainly on one geometric shape, the hexagon, when constructing their hives, and the graph shows that the western honeybee relies on the same nonhexagonal shapes as the dwarf honeybee does: five-sided, seven-sided, and eight-sided cells. In other words, the western honeybee and dwarf honeybee rely on the same number of geometric shapes. For the black dwarf honeybee, the graph displays data only for five-sided and seven-sided cells, which suggests a total absence of eight-sided cells. Yet this would be only one less nonhexagonal shape than is seen in the western honeybee. Thus, based on the graph, it would be inaccurate to say that the western honeybee relies on “many more” geometrical shapes than the other two species do. Choice D is incorrect. As the text explains, honeybee hives consist mainly of hexagonal cells, and sections of nonhexagonal cells are used to connect sections of hexagonal cells of different sizes. Since the graph indicates that the percentage of nonhexagonal cells is lower for the western honeybee than it is for the dwarf honeybee or black dwarf honeybee, the western honeybee would conversely have a higher percentage of hexagonal cells than the either the dwarf honeybee or black dwarf honeybee does, not a lower percentage."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Barboza and Trejos’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would most directly support Barboza and Trejos’s claim that rural female entrepreneurs who have received small loans from ALSOL are strategic in selling their goods less frequently than they could, even if it means missing payments. The text explains that borrowers in the ALSOL program use proceeds from their businesses to repay loans in equal weekly payments, with almost no penalty for missed payments. According to the text, Barboza and Trejos found that rural borrowers miss weekly payments in part because they don’t sell their goods as often as they could, a move the researchers claim allows the entrepreneurs to help increase profits for the goods they sell. Finding that the cost of bringing goods to towns with marketplaces is high for rural entrepreneurs but is largely independent of how many goods are brought would support the researchers’ claim: traveling to marketplaces less frequently would mean that a rural entrepreneur spends less on travel overall, and taking a large load of goods to a marketplace for essentially the same cost as taking a small load would allow the entrepreneur to more substantially offset the cost of travel with greater overall sales at the marketplace, resulting in more profit per good sold—even if those profits are earned less frequently and don’t support weekly loan payments."}, {"type": "paragraph", "text": "Choice A is incorrect because the finding that many marketplaces require entrepreneurs to pay the operators of the marketplace a fixed percentage of proceeds to be able to sell goods there wouldn’t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. With a fixed percentage of proceeds due to operators, the amount entrepreneurs have to pay operators would also be fixed regardless of frequency of selling. Choice B is incorrect because the finding that rural entrepreneurs can usually sell their goods for higher prices in cities than in their local areas but also face higher competition to sell goods in cities wouldn’t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. This is because both the higher prices and higher competition in cities would be stable factors—meaning there would be no clear reason for the rural entrepreneurs not to take every available chance to sell their goods in cities and to instead sell their goods in cities only sometimes. Choice C is incorrect because the finding that rural entrepreneurs have lower costs and thus tend to require smaller initial loans than urban entrepreneurs do has no bearing on rural borrowers strategically choosing to sell their goods less frequently than they could specifically to increase their profits per unit sold. The cost of producing goods doesn’t depend on the frequency with which an entrepreneur sells those goods, so lower frequency alone wouldn’t affect profits, and the initial loan amount is set and has nothing to do with how much profit is earned from each sale."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Anita Allen’s argument about judges citing philosophers in their judicial opinions. The text indicates that judges sometimes cite philosophers when writing their judicial opinions and that, according to Allen, judges tend to cite philosophers whose views are in agreement with those of the judges themselves. Allen claims, however, that the best judicial opinions consider potential objections and rebut them, which suggests that judges may be able to strengthen their opinions by including discussions of philosophers with views contrary to their own."}, {"type": "paragraph", "text": "Choice A is incorrect because Allen’s claim is that judges could improve their judicial opinions by citing philosophers who disagree with the views expressed in the opinions, which would necessarily require judges to consult philosophical works. Choice C is incorrect because there’s no discussion in the text about making judicial opinions more easily understood by any particular group of readers. The focus of the text is on Allen’s claim that judicial opinions could be strengthened by the inclusion of discussions of philosophers whose views disagree with those of the judges authoring the opinions. Choice D is incorrect because the text presents Allen’s argument that discussing philosophers whose views judges disagree with could strengthen judicial opinions, not that doing so could bring those opinions into line with views that are popular among philosophers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the conclusion that most logically follows from the text’s discussion of military veterans working in civilian government jobs in the United States. The text indicates that the proportion of military veterans working in civilian government jobs is considerably higher than the proportion of military veterans in the population as a whole. The text also notes that the unusually high representation of military veterans in these jobs may be a result of the organizational structures shared by civilian government entities and the military. Hence, it’s reasonable to infer that it’s the familiarity of the structures of civilian government that makes jobs there particularly attractive to military veterans."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t address what a typical relationship between military service and later career preferences would be, and there’s no indication that it’s atypical for veterans to work in civilian government jobs after they’ve left the military. On the contrary, the text suggests that many military veterans are drawn to such jobs. Choice C is incorrect because the text is focused on the high representation of military veterans in civilian government jobs and doesn’t address nonveterans or their possible interest in military service."}, {"type": "paragraph", "text": "Choice D is incorrect because the text conveys that military veterans may be particularly interested in civilian government jobs due to the familiarity of organizational structures that are already in place, but there’s no reason to think that this interest would mean that more civilian government jobs will start to require military experience."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of finite verbs in a relative clause. Relative clauses, such as the one beginning with “which,” require a finite verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite past tense verb “provided.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the non-finite participle “having provided” doesn’t supply the clause with a finite verb. Choice C is incorrect because the non-finite to-infinitive “to provide” doesn’t supply the clause with a finite verb. Choice D is incorrect because the non-finite participle “providing” doesn’t supply the clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is subject–verb agreement. The singular verb “allows” agrees in number with the singular subject “landing.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the plural verb “are allowing” doesn’t agree in number with the singular subject “landing.” Choice C is incorrect because the plural verb “have allowed” doesn’t agree in number with the singular subject “landing.” Choice D is incorrect because the plural verb “allow” doesn’t agree in number with the singular subject “landing.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is pronoun–antecedent agreement. The plural pronoun “they” agrees in number with the plural antecedent “woodcuts” and clearly identifies what was exhibited at the Smithsonian American Art Museum."}, {"type": "paragraph", "text": "Choice A is incorrect because the singular pronoun “it” doesn’t agree in number with the plural antecedent “woodcuts.” Choice C is incorrect because the singular pronoun “this” doesn’t agree in number with the plural antecedent “woodcuts.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the plural pronoun “some” is illogical in this context (referring to “some” of two woodcuts)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between a main clause and two supplementary elements. In this choice, the commas after “nickname” and “however” are correctly used to separate the supplementary adverb “however” from the main clause (“Scott-Heron… nickname”) on one side and the supplementary participial phrase (“feeling… bluesologist”) on the other."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to mark the boundary between the supplementary adverb “however” and the supplementary phrase (“feeling… bluesologist”). Choice B is incorrect because a semicolon can’t be used in this way to join the supplementary adverb “however” and the supplementary phrase (“feeling…bluesologist”). Choice D is incorrect because a semicolon can’t be used in this way to join the main clause (“Scott-Heron…nickname”) and the supplementary word and phrase (“however” and “feeling…bluesologist”). Moreover, placing the semicolon after “nickname” illogically signals that the following information (Scott-Heron’s feeling that the nickname didn’t encapsulate his devotion to the blues tradition) is contrary to the information in the previous clause (Scott-Heron’s resistance to the nickname)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to offset the proper noun “Yuree Lee” from the title “plant cell biologist” that describes Lee."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice D is incorrect because no punctuation is needed around the proper noun “Yuree Lee.” Setting the phrase off with punctuation suggests that it could be removed without affecting the coherence of the sentence, which isn’t the case."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use within a sentence. A colon can be used between two main clauses to signal that what follows is an elaboration of what came before. In this choice, the colon correctly introduces the following explanation of the divergent milk preservation strategies that emerged."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a run-on sentence. The main clause (“As…emerged”) and the subordinate clause followed by another main clause (“whereas…steppe”) are fused without punctuation and/or a conjunction. Choice B is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join a main clause (“As…emerged”) and a subordinate clause followed by another main clause (“whereas…steppe”). Choice D is incorrect because it results in a comma splice. A comma can’t be used in this way to join a main clause (“As…emerged”) and a subordinate clause followed by another main clause (“whereas…steppe”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle “suggesting” is correctly used to form a restrictive participial phrase (“suggesting...Holocene”) within the main clause (“This hypothesis...cannot stand...”). This participial phrase functions as part of the sentence’s subject (“This...Holocene”), providing essential identifying information about what the hypothesis states—namely, that certain trees survived without interruption or human intervention throughout the Holocene."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in an ungrammatical sentence. The finite verb “suggested” can’t be used in this way within the subject of the sentence."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in an ungrammatical sentence. The finite verb “suggests” can’t be used in this way within the subject of the sentence."}, {"type": "paragraph", "text": "Choice D is incorrect because it results in an ungrammatical sentence. The finite verb “has suggested” can’t be used in this way within the subject of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb “is” agrees in number with the singular subject “the shape.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “the shape.” Choice C is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “the shape.” Choice D is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “the shape.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Meanwhile” logically signals that the action described in this sentence (Obinze’s move to London to pursue a career) is simultaneous with the action described in the previous sentence (Ifemelu’s move to the United States). The first sentence establishes that the actions take place around the same time, referring to the characters’ “divergent experiences” following high school."}, {"type": "paragraph", "text": "Choice B is incorrect because “nevertheless” illogically signals that the information in this sentence about Obinze’s move to London is true despite the previous information about Ifemelu’s move to the United States. Instead, as the first sentence establishes, Obinze’s move and Ifemelu’s move are related, parallel experiences that occur around the same time. Choice C is incorrect because “secondly” illogically signals that the information in this sentence is a second point or reason separate from the previous information about Ifemelu’s move to the United States. Instead, as the first sentence establishes, Obinze’s move and Ifemelu’s move are related, parallel experiences that occur around the same time."}, {"type": "paragraph", "text": "Choice D is incorrect because “in fact” illogically signals that the information in this sentence emphasizes, modifies, or contradicts the previous information about Ifemelu’s move to the United States. Instead, as the first sentence establishes, Obinze’s move and Ifemelu’s move are related, parallel experiences that occur around the same time."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Additionally” logically signals that the claim in this sentence—that some Supreme Court justices worry that viewers (of televised court arguments) would watch only short, misleading clips—adds to the information in the previous sentence. Specifically, the previous sentence indicates one concern raised by those opposed to televising the court’s oral arguments, and the claim that follows indicates a second, additional concern."}, {"type": "paragraph", "text": "Choice A is incorrect because “however” illogically signals that the claim in this sentence contrasts with the information in the previous sentence. Instead, the claim adds to the information, indicating a second, additional concern that some Supreme Court justices have about televising the court’s arguments. Choice C is incorrect because “in comparison” illogically signals that the claim in this sentence is being compared to the information in the previous sentence. Instead, the claim adds to the information, indicating a second, additional concern that some Supreme Court justices have about televising the court’s arguments."}, {"type": "paragraph", "text": "Choice D is incorrect because “for example” illogically signals that the claim in this sentence exemplifies the information in the previous sentence. Instead, the claim adds to the information, indicating a second, additional concern that some Supreme Court justices have about televising the court’s arguments."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Thus” logically signals that the claim in this sentence—that animals performing only basic actions should allocate relatively few resources to their brain tissue—is a consequence of the previous sentence’s claim about the energy demands of animal brains (namely, that the more diverse an animal’s behaviors, the more energy its brain needs)."}, {"type": "paragraph", "text": "Choice A is incorrect because “subsequently” illogically signals that the claim in this sentence occurs later in a chronological sequence of events than the previous sentence’s claim about the energy demands of animal brains. Instead, the second claim is a consequence of the first. Choice B is incorrect because “besides” illogically signals that the claim in this sentence provides a separate point in addition to, or apart from, the previous sentence’s claim about the energy demands of animal brains. Instead, the second claim is a consequence of the first."}, {"type": "paragraph", "text": "Choice C is incorrect because “nevertheless” illogically signals that the claim in this sentence is true in spite of the previous sentence’s claim about the energy demands of animal brains. Instead, the second claim is a consequence of the first."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “By contrast” logically signals that the information in this sentence—that a firefly’s glow ceases when it stops drawing in oxygen— contrasts with the previous sentence’s discussion of the processes that cause a firefly to begin to glow."}, {"type": "paragraph", "text": "Choice A is incorrect because “for instance” illogically signals that the information in the sentence exemplifies the previous sentence’s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence’s discussion."}, {"type": "paragraph", "text": "Choice C is incorrect because “specifically” illogically signals that the information in the sentence provides specific details elaborating on the previous sentence’s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence’s discussion. Choice D is incorrect because “in conclusion” illogically signals that the information in the sentence sums up the previous sentence’s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence’s discussion."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence explains an advantage of microprobes, noting that because microprobes weigh as little as 50 milligrams, they can explore areas inaccessible to rovers."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence indicates that rovers can land successfully on Mars despite their weight; it doesn’t explain an advantage of microprobes."}, {"type": "paragraph", "text": "Choice C is incorrect. While the sentence mentions that microprobes have been proposed as an alternative to rovers, it doesn’t explain an advantage of microprobes. Choice D is incorrect. The sentence emphasizes a similarity between microprobes and rovers; it doesn’t explain an advantage of microprobes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes the significance of Ochoa’s discovery, noting that it proved critical to deciphering the human genetic code, which resulted in a better understanding of how genetic variations affect human health."}, {"type": "paragraph", "text": "Choice B is incorrect. While the sentence explains what Ochoa discovered, it doesn’t emphasize the significance of the discovery. Choice C is incorrect. While the sentence explains what Ochoa discovered, it doesn’t emphasize the significance of the discovery. Choice D is incorrect. While the sentence mentions that Ochoa’s discovery was crucial, it emphasizes Ochoa’s incorrect hypothesis, not the significance of the discovery."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence effectively introduces the poetry collection Precario/Precarious, noting that it is a collection by Vicuña that was published in 1983 by Tanam Press."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence mentions the 1983 poetry collection Precario/Precarious, it focuses mainly on Vicuña’s visual art. Choice B is incorrect. The sentence doesn’t introduce the 1983 poetry collection Precario/Precarious; instead, it introduces Vicuña. Choice D is incorrect. The sentence emphasizes the location of Vicuña’s 1971 exhibition Pinturas, poemas y explicaciones; it doesn’t introduce the 1983 poetry collection Precario/Precarious."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “completing” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because as used in the text, “completing” most nearly means finishing. In the text, the narrator conveys that the task of translating a novel has been an all-consuming one and that she hopes things will “be normal again” once she has “sent off the manuscript.” In other words, the narrator is looking forward to finishing her work on the manuscript and returning to other things."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “completing” doesn’t mean destroying, or ruining. The narrator addresses her desire to send off the manuscript she’s focused on and her hope that things will be “normal again” once she does, conveying that she is looking forward to finishing the work, not to ruining it. Choice C is incorrect because in this context, “completing” doesn’t mean advertising, or publicly promoting. The narrator addresses her complete focus on the translation and her hope that things will be “normal again” once she has “sent off the manuscript,” conveying that she is looking forward to finishing the task, not to promoting the resulting manuscript. Choice D is incorrect because in this context, “completing” doesn’t mean rejecting, or refusing or repelling. The narrator makes it clear that she is absorbed in working on the translation and plans to send off the manuscript, suggesting that instead of refusing to do the work, she is continuing to do it (even if she looks forward to things being “normal again” when she’s done)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of how predators feed their young. As used in this context, “provide” means supply or make something that’s needed available. The text indicates that some predators supply prey for their young by either leaving dead prey nearby or by bringing live prey to them. Other predators, the text states, feed their young directly from their own mouths. This context supports the idea that predatory animals have various ways to provide food for their young."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “avoid” would mean keep away from or refrain from, neither of which would make sense in context. Nothing in the text suggests that predators refrain from food for their young. Choice B is incorrect because in this context, “guess” would mean speculate or suppose, and it’s unclear what it would mean for predators to speculate food for their young."}, {"type": "paragraph", "text": "Choice D is incorrect because in this context, “describe” would mean explain, and it’s unclear what it would mean for predators to explain food for their young."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Cole’s book Blind Spot. In this context, “enthusiasm for” means excitement about. The text explains that Blind Spot consists of original photographs as well as poetic prose—two elements that correspond to Cole’s passions, identified in the text, for photography and the written word. This context suggests that Cole’s excitement about photography and writing led him to create a book that successfully combines the two mediums."}, {"type": "paragraph", "text": "Choice A is incorrect because describing Cole as feeling “indifference to” his two passions wouldn’t make sense in context. If Cole is indifferent to his passions, that would mean he doesn’t care about photography or writing—in which case they wouldn’t be his passions at all. Choice C is incorrect because there’s nothing in the text to suggest that Cole feels “concern about,” or uneasiness about, his passions. The text’s use of the word “culminates” indicates that Blind Spot represents a triumphant climax of Cole’s passions, not a work that results from his sense of discomfort with photography and writing. Choice D is incorrect because there’s nothing in the text to suggest that Cole feels “surprise at,” or astonished by, his passions. The text indicates that Cole’s feeling about his passions “culminates” in a book that “evocatively” combines photographs and writing, suggesting that Cole has a long-standing and skillful relationship to his passions, not that he is startled by them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Marilyn Dingle’s baskets. In this context, to say that Dingle’s baskets are “handmade from” particular plants means that Dingle creates baskets herself using those plants but without using machines. The text says that Dingle “skillfully winds” parts of palmetto palm plants around sweetgrass plants to make baskets with an appearance that “no factory can reproduce.” This context suggests that Dingle’s baskets are handmade from sweetgrass and palmetto palm."}, {"type": "paragraph", "text": "Choice A is incorrect because the text describes how Dingle uses sweetgrass and palmetto palm to create her baskets, not how her baskets are “indicated by,” or signified by, sweetgrass and palmetto palm. Choice C is incorrect. Although Dingle’s baskets are described as being made using sweetgrass and palm, there’s nothing in the text to suggest that the baskets are “represented by,” or exemplified or portrayed by, sweetgrass and palmetto palm. Instead, the focus of the text is on Dingle’s use of sweetgrass and palmetto palm and the impossibility of replicating the appearance of her baskets using machines. Choice D is incorrect because there’s nothing in the text to suggest that Dingle’s baskets are “collected with,” or brought together in a group with, sweetgrass and palmetto palm. Instead, the text describes how Dingle uses those plants to make her baskets."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Annie Dodge Wauneka’s work as a Navajo Nation legislator. As used in this context, “persistent” means existing continuously. The text states that Wauneka “continuously worked to promote public health,” traveling extensively and authoring a medical dictionary; this indicates that Wauneka’s effort was persistent."}, {"type": "paragraph", "text": "Choice A is incorrect because describing Wauneka’s effort related to public health as “impartial,” or not partial or biased and treating all things equally, wouldn’t make sense in context. The text suggests that Wauneka’s continuous work was partial in one way, as she focused specifically on promoting public health throughout the Navajo homeland and to speakers of the Navajo language."}, {"type": "paragraph", "text": "Choice B is incorrect because the text emphasizes that Wauneka’s effort to promote public health as a Navajo Nation legislator was continuous and extensive, involving wide travels and the authoring of a medical dictionary. Because this work clearly involved care and dedication, it wouldn’t make sense to describe it as “offhand,” or casual and informal. Choice D is incorrect because nothing in the text suggests that Wauneka’s effort to promote public health was “mandatory,” or required by law or rule, even though Wauneka was a Navajo Nation legislator. Rather than suggesting that Wauneka’s effort was required for any reason, the text emphasizes the continuous and extensive nature of her work."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The text begins by pointing out one of the advantages of oral histories: that they allow researchers to document the daily experiences of people. The text then goes on to describe how Karida Brown utilized interviews with coal miners and their families for her book about twentieth-century coal mining in Kentucky. The underlined sentence affirms that the general advantages of oral histories mentioned earlier in the text were also benefits in Brown’s particular case. Thus, the underlined sentence describes how Karida Brown benefited from incorporating oral history in her book."}, {"type": "paragraph", "text": "Choice A is incorrect because though the text mentions coal miners who live in Kentucky, the underlined sentence does not offer a geographical fact about Kentucky. Choice B is incorrect because the underlined sentence does not mention United States politics or that Brown is an expert in this particular area."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the text mentions that Brown’s book revolved around coal miners during the twentieth century, the underlined sentence does not focus on a major historical event during this time."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately states the text’s main purpose. The poem begins with the speaker urging a child to “go forth” with her encouragement (“my heart’s desire”). The speaker goes on to suggest that new experiences (“Great reaches, yet unknown”) lie ahead for the son that “life is calling” him to seek out. Thus, the main purpose is to encourage a child to embrace the experiences available to him in his life."}, {"type": "paragraph", "text": "Choice A is incorrect because the speaker encourages the child to pursue new experiences (“Great reaches”) without knowing exactly what those experiences will be (“yet unknown”) or suggesting that they should match the speaker’s own accomplishments. Choice B is incorrect because the speaker focuses on positive possibilities for her son (“Great reaches, yet unknown”) and her enthusiastic encouragement to embrace those possibilities (“life is calling you!”), while there is no mention of raising a child or associated struggles. Choice C is incorrect because the speaker frames the possibilities for her son in a positive light when she says that “great reaches, yet unknown” are waiting for him, and this positive outlook for the son is consistent throughout the text."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it best describes how the underlined sentence functions in the text as a whole. The first sentence of the text establishes that Lily can be “keenly sensitive to” scenes that serve as a “fitting background” for her feelings—that is, she’s very aware of when a setting seems to reflect her mood. The next sentence, which is underlined, then demonstrates this awareness: Lily views the landscape she’s in as a large-scale reflection of her current mood, identifying with elements such as its calmness. Thus, the function of the underlined sentence is to illustrate an idea introduced in the previous sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because the underlined sentence describes the scene only in very general terms, referring to its calmness, breadth, and long stretches of land. It’s the next sentence that adds specific details about colors, light, and various trees nearby. Choice B is incorrect because nothing in the underlined sentence suggests that Lily is experiencing an internal conflict. In fact, the sentence indicates that Lily thinks the landscape reflects her own feeling of calmness. Choice C is incorrect because the only assertion in the underlined sentence is that Lily feels that broad aspects of the landscape, such as its calmness, reflect her current mood, and that assertion isn’t expanded on in the next sentence. Instead, the next sentence describes specific details of the scene without connecting them to Lily’s feelings."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined statement in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined statement functions in the text as a whole. The underlined statement mentions a category of animals that have a feature in common: they tend to have fixed geographic ranges throughout their lifetimes. The text then presents the speculation of some researchers that the Arctic woolly mammoth might also share this characteristic. However, an examination of the content of strontium in the strata (or layers) of a woolly mammoth tusk indicated that contrary to the researchers’ hypothesis, the mammoth had an expanding range in its environment that contracted in its last 1.5 years of life. Thus, the underlined statement discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text."}, {"type": "paragraph", "text": "Choice B is incorrect. Though the underlined statement presents a pattern of behavior (the habit of certain animals of staying within a fixed geographic range), the rest of the text does not present a theory of exceptions to that pattern; rather, the researchers are merely concerned with whether one particular animal has behavior consistent with the pattern. Choice C is incorrect. Though the underlined statement does describe a similarity in the behavior of certain animals (their tendency to stay within a fixed geographic range), this is not done in order to show why a method described later in the text failed to show whether another animal showed that behavior; rather, the method of analysis of strata of a woolly mammoth tusk showed that the mammoth’s behavior was different from that of the animals mentioned in the underlined statement. Choice D is incorrect. Though the underlined statement mentions a trait shared by a number of animals (their fixed geographic range), the rest of the text does not present a hypothesis regarding the origin of that trait; rather, the researchers are concerned with whether another particular animal shares that trait."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what did Gloria Richardson lead?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents information about Gloria Richardson that is supported by the text. The text provides a number of details about Gloria’s involvement in efforts to promote racial equality, including that she was the leader of what became known as the Cambridge movement."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never indicates that Gloria Richardson led her daughter Donna’s high school. The text says only that Gloria was inspired by her daughter to become involved in efforts to promote racial equality. Choice C is incorrect because the text doesn’t mention protests related to environmental protections. Rather, the text discusses Gloria Richardson’s involvement in efforts to promote racial equality. Choice D is incorrect because the text doesn’t indicate that Gloria Richardson led a new business in Cambridge, Maryland. Rather, the text states that she led what became known as the Cambridge movement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what is true about Elinor?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it provides a detail about Elinor that is established in the text. The text indicates that although Elinor is “only nineteen,” she gives good advice and exhibits such a high level of understanding and judgment that she serves as “the counsellor of her mother.” Thus, Elinor is mature beyond her years."}, {"type": "paragraph", "text": "Choice A is incorrect because it isn’t supported by the text: although the text says that Elinor advises her mother and often counteracts her mother’s impulses, there’s no mention of Elinor arguing with her mother or failing to change her mother’s mind. Choice B is incorrect because it isn’t supported by the text: although the text mentions that Elinor has strong feelings, it doesn’t indicate that she’s excessively sensitive when it comes to family issues. Choice C is incorrect because it isn’t supported by the text: there’s no mention of what Elinor thinks about her mother and no suggestion that she thinks her mother is a bad role model. Because she’s described as having “an excellent heart,” Elinor likely doesn’t think ill of her mother."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately states the main idea of the text. The text describes the book Vibration Cooking: or, the Travel Notes of a Geechee Girl as Smart-Grosvenor’s “most influential project” and as “unusual for its time.” The text also notes that the book and author have influenced contemporary approaches to writing about food and cooking. Therefore, the text mainly conveys that Vibration Cooking: or, the Travel Notes of a Geechee Girl is an unconventional and important contribution to food writing."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the text mentions that Smart-Grosvenor worked in national public television and radio and was a food writer, these details aren’t the main focus. Rather than focusing on Smart-Grosvenor’s various jobs, the text focuses specifically on one specific book she wrote. Choice C is incorrect. Although the text suggests that Vibration Cooking: or, the Travel Notes of a Geechee Girl was groundbreaking, it doesn’t suggest that the book didn’t receive praise when it was published. In fact, the text states that the book is “long admired.” Choice D is incorrect because the text states that Smart-Grosvenor was a culinary anthropologist and that her book influenced later approaches to food writing but doesn’t indicate that Smart-Grosvenor or her book influenced people to begin cooking for themselves."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, what is true about Mrs. Ochiltree’s acquaintances?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a statement about Mrs. Ochiltree’s acquaintances that is supported by the text. The text indicates that Mrs. Ochiltree makes comments about her acquaintances that are frank, or direct and blunt, and sometimes startling. It also states that because of this behavior, the acquaintances tend to avoid Mrs. Ochiltree. Together, these details suggest that the acquaintances choose not to be around Mrs. Ochiltree because they are offended by the things she has said about them."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t suggest that Mrs. Ochiltree’s acquaintances avoid discussing topics that would upset Mrs. Ochiltree; instead, it states that they avoid being around Mrs. Ochiltree at all. Choice B is incorrect because the text makes it clear that Mrs. Ochiltree knows her acquaintances often avoid her and is pleased about it (she “rather exulted in it”), not that she wants to spend more time with them. Choice C is incorrect because the text doesn’t suggest that Mrs. Ochiltree’s acquaintances don’t speak with Mrs. Ochiltree because they are too focused on their own concerns, but rather because they don’t like the frank comments she makes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from Mrs. Spring Fragrance’s letters most effectively illustrates the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a quotation that illustrates the claim that Mrs. Spring Fragrance demonstrates concern for what’s happening at home while she’s in California. By giving reminders to “care for the cat, the birds, and the flowers,” “not eat too quickly,” and avoid engaging in strenuous activity in the heat, Mrs. Spring Fragrance shows that she’s thinking about what’s happening at home and wants to ensure everything is taken care of."}, {"type": "paragraph", "text": "Choice A is incorrect because the quotation, while it does suggest that Mrs. Spring Fragrance has made fudge at home before, is focused on preparations for an upcoming festival, not on concerns for anything happening at home while Mrs. Spring Fragrance is away. Choice B is incorrect because the quotation has to do with an upcoming event during Mrs. Spring Fragrance’s trip—visiting San José and meeting someone new—rather than her concern for what’s happening at home. Choice D is incorrect because the quotation is focused on how Mrs. Spring Fragrance feels about her trip and the friends she’s seeing, not on her concern for what’s happening at home."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly undermine Foster’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a finding that, if true, would weaken Foster’s hypothesis that damage to eelgrass roots improves the health of eelgrass meadows by boosting genetic diversity. The text indicates that sea otters damage eelgrass roots but that eelgrass meadows near Vancouver Island, where there’s a large otter population, are comparatively healthy. When Foster and her colleagues compared the Vancouver Island eelgrass meadows to those that don’t have established otter populations, the researchers found that the Vancouver Island meadows are more genetically diverse than the other meadows are. This finding led Foster to hypothesize that damage to the eelgrass roots encourages eelgrass reproduction, thereby improving genetic diversity and the health of the meadows. If, however, other meadows not included in the study are less healthy the larger the local otter population is and the longer the otters have been in residence, that would suggest that damage to the eelgrass roots, which would be expected to increase with the size and residential duration of the otter population, isn’t leading meadows to be healthier. Such a finding would therefore weaken Foster’s hypothesis."}, {"type": "paragraph", "text": "Choice A is incorrect because finding that small, recently introduced otter populations are near other eelgrass meadows in the study wouldn’t weaken Foster’s hypothesis. If otter populations were small and only recently established, they wouldn’t be expected to have caused much damage to eelgrass roots, so even if those eelgrass meadows were less healthy than the Vancouver Island meadows, that wouldn’t undermine Foster’s hypothesis. In fact, it would be consistent with Foster’s hypothesis since it would suggest that the greater damage caused by larger, more established otter populations is associated with healthier meadows. Choice B is incorrect because the existence of areas with otters but without eelgrass meadows wouldn’t reveal anything about whether the damage that otters cause to eelgrass roots ultimately benefits eelgrass meadows. Choice D is incorrect because the health of plants other than eelgrass would have no bearing on Foster’s hypothesis that damage to eelgrass roots leads to greater genetic diversity and meadow health. It would be possible for otters to have a negative effect on other plants while nevertheless improving the health of eelgrass meadows by damaging eelgrass roots."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Paredes’s argument?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would support Paredes’s argument about the origin of Mexican American folklore. The text describes a disagreement among scholars about whether Mexican American folklore mostly derived from the folklore of Spain (the view held by Espinosa and others) or originated in Mexico and the United States through ongoing cultural interactions there (the view held by Paredes and others). If Mexican American folklore collected in the twentieth century mostly consists of ballads about history and social life that originated recently, then that would support Paredes’s argument by suggesting that the folklore mostly arose after Spanish rule ended in the early nineteenth century and that the folklore reflects cultural interactions in Mexico and the United States rather than traditions from Spain."}, {"type": "paragraph", "text": "Choice A is incorrect because the inclusion of songs influenced by sixteenth- century Spanish poetry among Mexican American folklore collected in the twentieth century would not support Paredes’s view that the folklore was the result of cultural interactions in Mexico and the United States rather than an offshoot of Spanish folklore. If anything, the presence of such songs among the folklore collected in the twentieth century would weaken Paredes’s argument, since it would reflect the influence of Spanish culture on the folklore. Choice B is incorrect because the mere presence of similarities in Mexican American folklore across regions would not be sufficient to draw a conclusion about where the folklore originated, let alone to support Paredes’s argument that the folklore reflects various cultural interactions in Mexico and the United States. In fact, Paredes would likely expect there to be regional variations in folklore as different cultures have interacted in different places. Choice C is incorrect because scholars’ previous ignorance of the folklore would have no bearing on Paredes’s argument that Mexican American folklore mostly reflects cultural interactions in Mexico and the United States; the folklore’s actual origins exist regardless of the scholars’ awareness."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the study by Versace and colleagues. The text indicates that newborn animals of some species are attracted to faces and to stimuli that resemble faces. These species, the text says, share two characteristics: they’re social and they practice parental care, meaning that parents care for their young. The text goes on to describe Versace and colleagues’ experiment, which showed that Testudo tortoises, which aren’t social and don’t practice parental care, were attracted to a stimulus that resembles a face. Since Versace and colleagues have shown that a species that isn’t social and doesn’t practice parental care nevertheless has the innate characteristic of being attracted to face-like stimuli, it follows that this characteristic shouldn’t be assumed to be an adaptation related to social interaction or parental care."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that the tortoise hatchlings, which are solitary and don’t practice parental care, were attracted to the face-like stimuli, not that they perceived the stimuli as threatening. Choice C is incorrect because the phenomenon discussed in the text is an attraction to faces and face-like stimuli on the part of newborn animals, which can’t show any learned characteristics since they were just born. Additionally, the text tells us that the tortoises Versace and colleagues studied aren’t social and don’t practice parental care, so any findings about those tortoises wouldn’t be relevant to the question of whether an attraction to faces in social species that practice parental care is innate or learned. Choice D is incorrect because the text gives no indication that adult tortoises were tested on face-like stimuli and, if adults were in fact tested, no information about how they responded is provided. Since no information about adult tortoises’ responses is provided, no conclusion comparing those responses to the responses of newly hatched tortoises can be supported."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of aptamers’ capacity to test for pathogens in food. The text explains that although synthetic aptamer molecules can be used to test for foodborne bacterial pathogens because they bind to target molecules, it hasn’t been clear how likely it is that they will indicate a negative result when a target pathogen is absent in real-world foods. The text then indicates that Somvanshi et al. created test paper that changes from pink to purple when aptamers in it bind to a particular strain of E. coli bacteria, O157:H7, and tested it with store-bought pear juice (that is, a real-world food); the paper changed to purple when exposed to juice to which the target pathogen E. coli O157:H7 had been added, but it remained pink when exposed to juice treated with other E. coli strains or other bacteria species. Based on this result, it seems the aptamers in the paper successfully bound to the target (O157:H7) and the tests had a high degree of specificity (providing negative results for samples where the target was absent even though other bacteria were present) when applied to a real-world food."}, {"type": "paragraph", "text": "Choice A is incorrect because nothing in the text suggests that E. coli O157:H7 differs from other pathogens in a way that makes it more suitable for aptamer- based testing of any kind and that specificity is likely to be lower when aptamer- based tests target other bacteria; the text simply indicates that Somvanshi et al. used O157:H7 as the target for aptamer-based test paper in their study and suggests that the paper had a high degree of specificity. Choice B is incorrect because the text indicates that the specificity of aptamer-based tests in real- world foods is uncertain for pathogens broadly, not just for E. coli, and similarity between strains (of E. coli or of other pathogens) isn’t mentioned. Moreover, the results presented in the text suggest that aptamers are actually capable of distinguishing between strains of E. coli, since Somvanshi et al.’s paper turned purple when exposed to E. coli O157:H7 and remained pink when exposed to other strains. Choice C is incorrect because the text suggests that the aptamers in the test papers didn’t bind to different strains of E. coli. The text explains that the test papers turn purple when the aptamers bind to the targeted pathogen and that in the pear juice tests, the test papers turned purple when exposed to samples with the targeted strain of E. coli (O157:H7) but remained pink when exposed to samples with other strains of E. coli. In other words, the aptamers bound only to the targeted strain, not to the other strains. Further, specificity would be affected if the aptamers had bound to multiple strains and not just the targeted one; that result would cause the specificity to be low."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of possessive determiners. The plural possessive determiner “their” agrees in number with the plural conjoined noun phrase “Watson and Crick” and thus indicates that the findings were those of Watson and Crick."}, {"type": "paragraph", "text": "Choice A is incorrect because “they’re” is the contraction for “they are,” not a possessive determiner. Choice B is incorrect because “it’s” is the contraction for “it is” or “it has,” not a possessive determiner. Choice D is incorrect because the singular possessive determiner “its” doesn’t agree in number with the plural conjoined noun phrase “Watson and Crick.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite to-infinitive “to tell” is correctly used to form a nonfinite (infinitive) clause that explains the reason Engle uses poetry in her novel."}, {"type": "paragraph", "text": "Choice A is incorrect because the finite present tense verb “tells” can’t be used in this way to explain the reason that Engle uses poetry in her novel. Choice B is incorrect because the finite past tense verb “told” can’t be used in this way to explain the reason that Engle uses poetry in her novel. Choice C is incorrect because the finite present progressive tense verb “is telling” can’t be used in this way to explain the reason that Engle uses poetry in her novel."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The plural verb “study” agrees in number with the plural subject “many.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the singular verb “is studying” doesn’t agree in number with the plural subject “many.” Choice B is incorrect because the singular verb “has studied” doesn’t agree in number with the plural subject “many.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the singular verb “studies” doesn’t agree in number with the plural subject “many.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation between a subject and a verb. When, as in this case, a subject (“her 2019 novel Gingerbread”) is immediately followed by a verb (“offers”), no punctuation is needed."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the subject and the verb. Choice B is incorrect because no punctuation is needed between the subject and the verb. Choice D is incorrect because no punctuation is needed between the subject and the verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“Gitlin’s…content”) and the second main clause beginning with a supplementary phrase (“in…audiences”). Further, placing a comma after “era” separates the supplementary phrase “in that era” from the rest of the main clause that follows (“even…audiences”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Further, this choice fails to mark the boundary between the supplementary phrase “in that era” and the rest of the main clause that follows (“even…audiences”). Choice C is incorrect because it results in a run-on sentence. The two main clauses (“Gitlin’s… content” and “in…audiences”) are fused without punctuation and/or a conjunction."}, {"type": "paragraph", "text": "Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation around noun phrases. No punctuation is needed because the noun phrase “aluminum oxide” is a restrictive appositive, meaning that it provides essential identifying information about the noun phrase before it, “the chemical compound,” and thus doesn’t require punctuation around it."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice C is incorrect because the noun phrase “aluminum oxide” is a restrictive appositive. Setting the phrase off with punctuation suggests that it could be removed without affecting the coherence of the sentence, which isn’t the case."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verb forms in a sentence. The nonfinite past participle phrase “highly prized” is correctly used to form a supplementary element that modifies the main clause “this…artistry,” describing memorable features of Brass Era automotive design."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Using the finite present tense verb phrase “are highly prized” creates a second main clause in the sentence, and two main clauses can’t be joined in this way with only a comma after “artistry.” Choice B is incorrect because it results in a comma splice. Using the finite past perfect tense verb phrase “had been highly prized” creates a second main clause in the sentence, and two main clauses can’t be joined in this way with only a comma after “artistry.” Choice D is incorrect because it results in a comma splice. Using the finite past tense verb phrase “were highly prized” creates a second main clause in the sentence, and two main clauses can’t be joined in this way with only a comma after “artistry.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “though” from the preceding main clause (“Economists…conservation”) and uses a semicolon to join the next main clause (“efficiency gains…rises”) to the rest of the sentence. Further, placing the semicolon after “though” indicates that the information in the preceding main clause (“improvements in efficiency often correlate negatively with resource conservation”) is contrary to what might be assumed from the information in the previous sentence (resource consumption would be expected to decrease with the development of new, more efficient technologies)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Commas can’t be used in this way to punctuate a supplementary word or phrase between two main clauses. Choice B is incorrect because it fails to mark the boundary between the two main clauses (“Economists...though” and “efficiency gains…rises”) with appropriate punctuation. Moreover, placing the semicolon after “conservation” illogically indicates that the information in the next clause (gains in efficiency may lead to an increase in resource consumption) is contrary to the information in the previous clause (“improvements in efficiency often correlate negatively with resource conservation”). Choice D is incorrect because placing a comma after “conservation” illogically indicates that the information in the next clause (gains in efficiency may lead to an increase in resource consumption) is contrary to the information in the previous clause (“improvements in efficiency often correlate negatively with resource conservation”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “Similarly” logically signals that the activity described in this sentence (Nancy Tuttle Craig distributing Votes for Women Tea in her Los Angeles grocery stores) is like the activity described in the previous sentence (the Woman’s Suffrage Party selling Equality Tea at fairs in San Francisco). Together, the two examples support the preceding claim that “activists across the state sold tea to promote the cause of suffrage.”"}, {"type": "paragraph", "text": "Choice A is incorrect because “for example” illogically signals that the activity described in this sentence exemplifies the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women’s right to vote. Choice B is incorrect because “to conclude” illogically signals that the activity described in this sentence concludes or summarizes the information in the previous sentences. Instead, the activity is similar to the one described in the previous sentence, and both support the preceding claim about selling tea to promote women’s right to vote. Choice D is incorrect because “in other words” illogically signals that the activity described in this sentence paraphrases the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women’s right to vote."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Specifically” logically signals that the information in this sentence—that the Sun releases charged particles that later collide with atoms, resulting in auroral light—provides specific, precise details about how auroras result from the Sun’s activity."}, {"type": "paragraph", "text": "Choice B is incorrect because “similarly” illogically signals that the information in this sentence is similar to the general information about auroras in the previous sentence. Instead, this sentence provides specific, precise details about how auroras form. Choice C is incorrect because “nevertheless” illogically signals that the information in this sentence is despite the general information about auroras in the previous sentence. Instead, this sentence provides specific, precise details about how auroras form. Choice D is incorrect because “hence” illogically signals that the information in this sentence is a result of the general information about auroras in the previous sentence. Instead, this sentence provides specific, precise details about how auroras form."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence compares the lengths of the two rail tunnels, noting that the Channel Tunnel (about 31 miles long) is slightly shorter than the Seikan Tunnel (roughly 33 miles long)."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence makes a generalization about the length of some rail tunnels; it doesn’t compare the lengths of the two rail tunnels. Choice C is incorrect. The sentence describes a single rail tunnel; it doesn’t compare the lengths of the two rail tunnels. Choice D is incorrect. While the sentence mentions the two rail tunnels, it doesn’t compare their lengths."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence effectively emphasizes the fossil’s significance, explaining that the fossil is rare and illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes the fossil Rybczynski found; it doesn’t emphasize the fossil’s significance. Choice B is incorrect. The sentence mentions that a fossil resembling both pinnipeds and their ancestors was found; it doesn’t emphasize the fossil’s significance. Choice D is incorrect. The sentence notes a term used to describe the fossil Rybczynski found; it doesn’t emphasize the fossil’s significance."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence uses “whereas” to contrast the emissivities of the two fibers, noting that the emissivity of the reflective metal fibers was just 0.02, far lower than that of the silicon carbide fibers (0.74)."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes the ability of reflective metal fibers and silicon carbide fibers to emit heat; it doesn’t contrast the emissivities of the two fibers. Choice B is incorrect. The sentence states a law of thermodynamics: the amount of heat a material absorbs is equal to the amount it emits. The sentence doesn’t contrast the emissivity of reflective metal fibers with that of silicon carbide fibers. Choice C is incorrect. While the sentence includes a generalization about the emissivities of reflective metal fibers and silicon carbide fibers, it emphasizes Abebe’s plans for their use in a garment; it doesn’t contrast the emissivities of the two fibers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence explains an advantage of the “Women and the Vote” format, noting that the format appealed to audiences because it allowed them to control the experience."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes a digital drawing on the “Women and the Vote” website; it doesn’t explain an advantage of the play’s format."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence explains how audiences interacted with the “Women and the Vote” website; it doesn’t explain an advantage of the play’s format. Choice D is incorrect. While the sentence mentions that “Women and the Vote” had an interactive format, it doesn’t explain what advantage this format might have."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence presents both the study and its methodology (that is, the researcher’s approach to the problem), explaining that Yuan used computer simulations to study the effect of the mother duck’s wake on the ducklings’ energy expenditure."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes the findings of Yuan’s study; it doesn’t present the study and its methodology. Choice C is incorrect. While the sentence provides general information about Yuan’s study, it doesn’t present the study’s methodology. Choice D is incorrect. The sentence describes the findings of Yuan’s study; it doesn’t present the study and its methodology."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 9: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-9-math') then
    raise notice 'skipping sat-practice-test-9-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-9-math', 'SAT Practice Test 9: Math', 'Official SAT Practice Test 9 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 219, '[[200, 200], [210, 220], [210, 220], [210, 230], [210, 240], [210, 250], [220, 260], [240, 270], [250, 280], [260, 300], [280, 340], [310, 350], [320, 360], [330, 370], [340, 380], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [500, 540], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [610, 670], [620, 680], [630, 690], [650, 710], [660, 720], [680, 740], [690, 750], [710, 760], [730, 770], [750, 780], [770, 800], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The lengths of two sides of a triangle are $4$ centimeters and $6$ centimeters. If the perimeter of the triangle is $18$ centimeters, what is the length, in centimeters, of the third side of this triangle?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$18 - 4 - 6 = 8$ centimeters."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "16x + 30 = 190"}, {"type": "paragraph", "text": "Which equation has the same solution as the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtracting $30$ from both sides gives the equivalent equation $16x = 160$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Ty set a goal to walk at least $24$ kilometers every day to prepare for a multiday hike. On a certain day, Ty plans to walk at an average speed of $4$ kilometers per hour. What is the minimum number of hours Ty must walk on that day to fulfill the daily goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$24 \\div 4 = 6$ hours."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = x^2 + 9$. For which value of $x$ is $g(x) = 25$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x^2 + 9 = 25$ gives $x^2 = 16$, so $x = 4$ (or $-4$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $9x^2 + 5x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor out $x$: $x(9x + 5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Each value in the data set shown represents the height, in centimeters, of a plant."}, {"type": "math", "latex": "6, 10, 13, 2, 15, 22, 10, 4, 4, 4"}, {"type": "paragraph", "text": "What is the mean height, in centimeters, of these plants?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The sum is $90$ and there are $10$ values, so the mean is $9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A student council group is selling school posters for a fundraiser. They use the function $p(x) = 5x - 220$ to determine their profit $p(x)$, in dollars, for selling $x$ school posters. In order to earn a profit of $\\$900$, how many school posters must they sell?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x - 220 = 900$, so $5x = 1{,}120$ and $x = 224$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['224']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Jay walks at a speed of $3$ miles per hour and runs at a speed of $5$ miles per hour. He walks for $w$ hours and runs for $r$ hours for a combined total of $14$ miles. Which equation represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distance is speed times time: $3w$ miles walking and $5r$ miles running, for a total of $14$: $3w + 5r = 14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "John paid a total of $\\$165$ for a microscope by making a down payment of $\\$37$ plus $p$ monthly payments of $\\$16$ each. Which of the following equations represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The monthly payments total $16p$, plus the $\\$37$ down payment: $16p + 37 = 165$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y - 57 = px"}, {"type": "paragraph", "text": "The given equation relates the positive numbers $p$, $x$, and $y$. Which equation correctly expresses $y$ in terms of $p$ and $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add $57$ to both sides: $y = px + 57$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A company opens an account with an initial balance of $\\$36{,}100.00$. The account earns interest, and no additional deposits or withdrawals are made. The account balance is given by an exponential function $A$, where $A(t)$ is the account balance, in dollars, $t$ years after the account is opened. The account balance after $13$ years is $\\$68{,}071.93$. Which equation could define $A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The initial value $A(0)$ must be $36{,}100.00$, and the balance grows, so the base is greater than $1$: $A(t) = 36{,}100.00(1.05)^t$. (Check: $36{,}100(1.05)^{13} \\approx 68{,}072$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m1-q12.png", "alt": "Figure for question 12", "width": 288}, {"type": "paragraph", "text": "The circle shown has center $O$, circumference $144\\pi$, and diameters $\\overline{PR}$ and $\\overline{QS}$. The length of arc $PS$ is twice the length of arc $PQ$. What is the length of arc $QR$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Arcs $PQ$ and $PS$ together make a semicircle ($72\\pi$), and $PS = 2 \\cdot PQ$, so $PQ = 24\\pi$ and $PS = 48\\pi$. Arc $QR$ is opposite arc $PS$ (vertical central angles), so it is also $48\\pi$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= -2x \\\\ 3x + y &= 40 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $3x - 2x = 40$, so $x = 40$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['40']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m1-q14.png", "alt": "Figure for question 14", "width": 153}, {"type": "paragraph", "text": "The frequency table summarizes the $57$ data values in a data set. What is the maximum data value in the data set?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The largest data value with a nonzero frequency is $14$ (frequency $6$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 14, 'spr', array['14']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "One leg of a right triangle has a length of $43.2$ millimeters. The hypotenuse of the triangle has a length of $196.8$ millimeters. What is the length of the other leg of the triangle, in millimeters?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt{196.8^2 - 43.2^2} = \\sqrt{36{,}864} = 192$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A wire with a length of $106$ inches is cut into two parts. One part has a length of $x$ inches, and the other part has a length of $y$ inches. The value of $x$ is $6$ more than $4$ times the value of $y$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x + y = 106$ and $x = 4y + 6$, so $5y + 6 = 106$, $y = 20$, and $x = 86$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (x + 6)(x + 5)(x - 4)"}, {"type": "paragraph", "text": "The function $f$ is given. Which table of values represents $y = f(x) - 3$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(-6) = f(-5) = f(4) = 0$, so $f(x) - 3 = -3$ at each of these $x$-values."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A landscaper uses a hose that puts $88x$ ounces of water in a bucket in $5y$ minutes. Which expression represents the number of ounces of water the hose puts in the bucket in $9y$ minutes at this rate?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The rate is $\\dfrac{88x}{5y}$ ounces per minute, so in $9y$ minutes: $\\dfrac{88x}{5y} \\cdot 9y = \\dfrac{792x}{5}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 4x - 9y &= 9y + 5 \\\\ hy &= 2 + 4x \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $h$ is a constant. If the system has no solution, what is the value of $h$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rewrite: $4x - 18y = 5$ and $4x - hy = -2$. These are parallel with different constants when $h = 18$, so there is no solution."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "$13$ is $p\\%$ of $25$. What is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{13}{25} = 0.52$, so $p = 52$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 20, 'spr', array['52']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\sqrt{(x - 2)^2} = \\sqrt{3x + 34}"}, {"type": "paragraph", "text": "What is the smallest solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Square both sides: $(x - 2)^2 = 3x + 34$, so $x^2 - 7x - 30 = 0$ and $(x - 10)(x + 3) = 0$. Both $10$ and $-3$ check in the original equation; the smaller is $-3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['-3']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Function $f$ is defined by $f(x) = (x + 6)(x + 5)(x + 1)$. Function $g$ is defined by $g(x) = f(x - 1)$. The graph of $y = g(x)$ in the $xy$-plane has $x$-intercepts at $(a, 0)$, $(b, 0)$, and $(c, 0)$, where $a$, $b$, and $c$ are distinct constants. What is the value of $a + b + c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g(x) = 0$ when $x - 1$ is a zero of $f$: $-6$, $-5$, or $-1$. So $x = -5$, $-4$, or $0$, and the sum is $-9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For $x > 0$, the function $f$ is defined as follows:"}, {"type": "paragraph", "text": "$f(x)$ equals $201\\%$ of $x$"}, {"type": "paragraph", "text": "Which of the following could describe this function?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = 2.01x$, a line with positive slope: increasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 4x^2 + 64x + 262"}, {"type": "paragraph", "text": "The function $g$ is defined by $g(x) = f(x + 5)$. For what value of $x$ does $g(x)$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f$ has its minimum at $x = -\\dfrac{64}{2(4)} = -8$. $g(x) = f(x + 5)$ reaches it when $x + 5 = -8$, so $x = -13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "One gallon of stain will cover $170$ square feet of a surface. A yard has a total fence area of $w$ square feet. Which equation represents the total amount of stain $S$, in gallons, needed to stain the fence in this yard twice?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Two coats cover $2w$ square feet, which needs $\\dfrac{2w}{170} = \\dfrac{w}{85}$ gallons."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["Poll Results", ""], "rows": [["Angel Cruz", "$483$"], ["Terry Smith", "$320$"]]}, {"type": "paragraph", "text": "The table shows the results of a poll. A total of $803$ voters selected at random were asked which candidate they would vote for in the upcoming election. According to the poll, if $6{,}424$ people vote in the election, by how many votes would Angel Cruz be expected to win?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In the poll Cruz led by $483 - 320 = 163$ of $803$ voters. Scaling to $6{,}424$ voters (a factor of $8$): $163 \\times 8 = 1{,}304$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Right rectangular prism X is similar to right rectangular prism Y. The surface area of right rectangular prism X is $58$ square centimeters (cm$^2$), and the surface area of right rectangular prism Y is $1{,}450$ cm$^2$. The volume of right rectangular prism Y is $1{,}250$ cubic centimeters (cm$^3$). What is the sum of the volumes, in cm$^3$, of right rectangular prism X and right rectangular prism Y?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The area ratio is $\\tfrac{1{,}450}{58} = 25$, so the length ratio is $5$ and the volume ratio is $125$. Prism X has volume $\\tfrac{1{,}250}{125} = 10$, and the sum is $1{,}260$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['1260']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "w + 7 = 357"}, {"type": "paragraph", "text": "What value of $w$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$w = 357 - 7 = 350$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $16(x + 15)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distribute: $16x + 16(15) = 16x + 240$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["", "Live east of the river", "Live west of the river", "Total"], "rows": [["Less than $40$ years old", "$17$", "$11$", "$28$"], ["At least $40$ years old", "$18$", "$89$", "$107$"], ["Total", "$35$", "$100$", "$135$"]]}, {"type": "paragraph", "text": "The table summarizes members of a local organization by age and whether they live east or west of the river. If a member of the organization is selected at random, what is the probability that the selected member is at least $40$ years old?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$107$ of the $135$ members are at least $40$ years old, so the probability is $\\tfrac{107}{135}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 3x &= 12 \\\\ -3x + y &= -6 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$3x = 12$, so $-12 + y = -6$ and $y = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A line in the $xy$-plane has a slope of $\\dfrac{1}{9}$ and passes through the point $(0, 14)$. Which equation represents this line?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Slope $\\tfrac{1}{9}$ and $y$-intercept $14$: $y = \\tfrac{1}{9}x + 14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m2-q06.png", "alt": "Figure for question 6", "width": 228}, {"type": "paragraph", "text": "In the figure shown, line $c$ intersects parallel lines $s$ and $t$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $110^\\circ$ angle at line $t$ and the angle corresponding to it at line $s$ are equal, and angle $x$ forms a straight line with that angle, so $x = 180 - 110 = 70$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 6, 'spr', array['70']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = x + \\frac{8}{11}"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. What is the value of $f(x)$ when $x = \\dfrac{3}{11}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{3}{11} + \\dfrac{8}{11} = \\dfrac{11}{11} = 1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['1']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$y$"], "rows": [["$0$", "$18$"], ["$1$", "$13$"], ["$2$", "$8$"]]}, {"type": "paragraph", "text": "The table shows three values of $x$ and their corresponding values of $y$. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "When $x = 0$, $y = 18$, and $y$ decreases by $5$ for each increase of $1$ in $x$: $y = -5x + 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x + 7 &= 10 \\\\ (x + 7)^2 &= y \\end{aligned}"}, {"type": "paragraph", "text": "Which ordered pair $(x, y)$ is a solution to the given system of equations?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x + 7 = 10$, so $x = 3$ and $y = 10^2 = 100$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 7x - 84$. What is the $x$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$7x - 84 = 0$ gives $x = 12$, so the $x$-intercept is $(12, 0)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m2-q11.png", "alt": "Figure for question 11", "width": 243}, {"type": "paragraph", "text": "Rosa opened a savings account at a bank. The table shows the exponential relationship between the time $t$, in years, since Rosa opened the account and the total amount $n$, in dollars, in the account. If Rosa made no additional deposits or withdrawals, which of the following equations best represents the relationship between $t$ and $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The starting amount is $604$ and it grows by $\\tfrac{606.42 - 604}{604} \\approx 0.004$ each year: $n = 604(1 + 0.004)^t$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "w(t) = 300 - 4t"}, {"type": "paragraph", "text": "The function $w$ models the volume of liquid, in milliliters, in a container $t$ seconds after it begins draining from a hole at the bottom. According to the model, what is the predicted volume, in milliliters, draining from the container each second?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The volume drops by $4$ milliliters for each second ($-4t$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "h(x) = x + b"}, {"type": "paragraph", "text": "For the linear function $h$, $b$ is a constant and $h(0) = 45$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(0) = 0 + b = 45$, so $b = 45$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['45']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "z^2 + 10z - 24 = 0"}, {"type": "paragraph", "text": "What is one of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor: $(z + 12)(z - 2) = 0$, so $z = 2$ or $z = -12$. Either is correct."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['2', '-12']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangle $FGH$ is similar to triangle $JKL$, where angle $F$ corresponds to angle $J$ and angles $G$ and $K$ are right angles. If $\\sin(F) = \\dfrac{308}{317}$, what is the value of $\\sin(J)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Corresponding angles of similar triangles are equal, so $\\sin(J) = \\sin(F) = \\tfrac{308}{317}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The population of Greenville increased by $7\\%$ from $2015$ to $2016$. If the $2016$ population is $k$ times the $2015$ population, what is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A $7\\%$ increase multiplies by $1 + 0.07 = 1.07$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m2-q17.png", "alt": "Figure for question 17", "width": 306}, {"type": "paragraph", "text": "Each of the dot plots shown represents the number of glue sticks brought in by each student for two classes, class A and class B. Which statement best compares the standard deviations of the numbers of glue sticks brought in by each student for these two classes?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The two dot plots have exactly the same shape; class B''s values are class A''s shifted up by $13$. Shifting every value does not change the spread, so the standard deviations are equal."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "m(t) = -0.0274\\left(\\frac{t}{7}\\right)^2 + 7.3873\\left(\\frac{t}{7}\\right) + 75.032"}, {"type": "paragraph", "text": "The function $m$ gives the predicted body mass $m(t)$, in kilograms (kg), of a certain animal $t$ days after it was born in a wildlife reserve, where $t \\le 390$. Which of the following is the best interpretation of the statement \"$m(330)$ is approximately equal to $362$\" in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The input $t = 330$ is days after birth and the output $362$ is the predicted mass in kilograms."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangle $XYZ$ is similar to triangle $RST$ such that $X$, $Y$, and $Z$ correspond to $R$, $S$, and $T$, respectively. The measure of $\\angle Z$ is $20^\\circ$ and $2XY = RS$. What is the measure of $\\angle T$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Similar triangles have equal corresponding angles, whatever the scale factor, so $\\angle T = \\angle Z = 20^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(t) = 60{,}000(2)^{\\frac{t}{410}}$ gives the number of bacteria in a population $t$ minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The base $2$ is raised to $\\tfrac{t}{410}$, so the population doubles every $410$ minutes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 20, 'spr', array['410']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = a^x + b$, where $a$ and $b$ are constants and $a > 0$. In the $xy$-plane, the graph of $y = f(x)$ has a $y$-intercept at $(0, -25)$ and passes through the point $(2, 23)$. What is the value of $a + b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 1 + b = -25$, so $b = -26$. Then $a^2 - 26 = 23$, so $a = 7$ and $a + b = -19$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['-19']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y > 13x - 18"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$13x - 18$ equals $21$, $47$, and $86$ at $x = 3$, $5$, $8$. Only table D has every $y$ strictly greater: $26$, $52$, $91$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A certain town has an area of $4.36$ square miles. What is the area, in **square yards**, of this town? ($1$ mile $= 1{,}760$ yards)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "One square mile is $1{,}760^2 = 3{,}097{,}600$ square yards, so $4.36 \\times 3{,}097{,}600 = 13{,}505{,}536$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A square is inscribed in a circle. The radius of the circle is $\\dfrac{20\\sqrt{2}}{2}$ inches. What is the side length, in inches, of the square?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The diagonal of the square is a diameter: $20\\sqrt{2}$. A square''s diagonal is its side times $\\sqrt{2}$, so the side is $20$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{y + 12}{x - 8} + \\dfrac{y(x - 8)}{x^2y - 8xy}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Over the common denominator $xy(x - 8) = x^2y - 8xy$: the first fraction becomes $\\dfrac{xy(y + 12)}{x^2y - 8xy}$, so the sum is $\\dfrac{xy^2 + 12xy + xy - 8y}{x^2y - 8xy} = \\dfrac{xy^2 + 13xy - 8y}{x^2y - 8xy}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = a(2.2^x + 2.2^b)$, where $a$ and $b$ are integer constants and $0 < a < b$. The functions $g$ and $h$ are equivalent to function $f$, where $k$ and $m$ are constants. Which of the following equations displays the $y$-coordinate of the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane as a constant or coefficient?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } g(x) = a(2.2^x + k) \\\\ &\\text{II. } h(x) = a(2.2)^x + m \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $y$-intercept is $f(0) = a(1 + 2.2^b)$. In I, $k = 2.2^b$, so the intercept is $a(1 + k)$; in II, $m = a(2.2^b)$, so the intercept is $a + m$. Neither shows it directly as a single constant or coefficient."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x(kx - 56) = -16"}, {"type": "paragraph", "text": "In the given equation, $k$ is an integer constant. If the equation has no real solution, what is the least possible value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rewrite as $kx^2 - 56x + 16 = 0$. No real solution requires $56^2 - 4(k)(16) < 0$: $3{,}136 < 64k$, so $k > 49$. The least integer is $50$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['50']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
