    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Diego Velázquez was the leading artist in the court of King Philip IV of Spain during the seventeenth century, but his influence was hardly ______ Spain: realist and impressionist painters around the world employed his techniques and echoed elements of his style."}]}'::jsonb, 'source') returning id into v_stim;
