    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Some members of the US Supreme Court have resisted calls to televise the court’s oral arguments, concerned that the participants would be tempted to perform for the cameras (and thus lower the quality of the discourse). ______ the justices worry that most viewers would not even watch the full deliberations, only short clips that could be misinterpreted and mischaracterized."}]}'::jsonb, 'source') returning id into v_stim;
