    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "A firefly uses specialized muscles to draw oxygen into its lower abdomen through narrow tubes, triggering a chemical reaction whereby the oxygen combines with chemicals in the firefly’s abdomen to produce a glow. ______ when the firefly stops drawing in oxygen, the reaction—and the glow—cease."}]}'::jsonb, 'source') returning id into v_stim;
