    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["NASA uses rovers, large remote vehicles with wheels, to explore the surface of Mars.", "NASA’s rovers can’t explore regions inaccessible to wheeled vehicles.", "Rovers are also heavy, making them difficult to land on the planet’s surface.", "Microprobes, robotic probes that weigh as little as 50 milligrams, could be deployed virtually anywhere on the surface of Mars.", "Microprobes have been proposed as an alternative to rovers."]}, {"type": "paragraph", "text": "The student wants to explain an advantage of microprobes."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Despite being heavy, NASA’s rovers can land successfully on the surface of Mars."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Microprobes, which weigh as little as 50 milligrams, could explore areas of Mars that are inaccessible to NASA’s heavy, wheeled rovers."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "NASA currently uses its rovers on Mars, but microprobes have been proposed as an alternative."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Though they are different sizes, both microprobes and rovers can be used to explore the surface of Mars."}]}'::jsonb, false);
