    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Severo Ochoa discovered the enzyme PNPase in 1955.", "PNPase is involved in both the creation and degradation of mRNA.", "Ochoa incorrectly hypothesized that PNPase provides the genetic blueprints for mRNA.", "The discovery of PNPase proved critical to deciphering the human genetic code.", "Deciphering the genetic code has led to a better understanding of how genetic variations affect human health."]}, {"type": "paragraph", "text": "The student wants to emphasize the significance of Ochoa’s discovery."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Ochoa’s 1955 discovery of PNPase proved critical to deciphering the human genetic code, leading to a better understanding of how genetic variations affect human health."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Ochoa first discovered PNPase, an enzyme that he hypothesized contained the genetic blueprints for mRNA, in 1955."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "In 1955, Ochoa discovered the PNPase enzyme, which is involved in both the creation and degradation of mRNA."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Though his discovery of PNPase was critical to deciphering the human genetic code, Ochoa incorrectly hypothesized that the enzyme was the source of mRNA’s genetic blueprints."}]}'::jsonb, false);
