    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Cecilia Vicuña is a multidisciplinary artist.", "In 1971, her first solo art exhibition, Pinturas, poemas y explicaciones, was shown at the Museo Nacional de Bellas Artes in Santiago, Chile.", "Her poetry collection Precario/Precarious was published in 1983 by Tanam Press.", "Her poetry collection Instan was published in 2002 by Kelsey St. Press.", "She lives part time in Chile, where she was born, and part time in New York."]}, {"type": "paragraph", "text": "The student wants to introduce the artist’s 1983 poetry collection."}]}'::jsonb, 'source') returning id into v_stim;
