    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 37);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Beginning in the 1950s, Navajo Nation legislator Annie Dodge Wauneka continuously worked to promote public health; this ______ effort involved traveling throughout the vast Navajo homeland and writing a medical dictionary for speakers of Diné bizaad, the Navajo language."}]}'::jsonb, 'source') returning id into v_stim;
