    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "impartial"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "offhand"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "persistent"}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "mandatory"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 38);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Oral histories—whether they consist of interviews or recordings of songs and stories—can offer researchers a rich view of people’s everyday experiences. For her book about coal mining communities in Kentucky during the twentieth century, Karida Brown therefore relied in part on interviews with coal miners and their families. [[0|By doing so, she gained valuable insights into her subjects’ day-to-day lives]]."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It provides a little-known geographical fact about Kentucky."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It argues that Karida Brown is an expert on United States politics."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It presents a major historical event that took place in the twentieth century."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It describes how Karida Brown benefited from incorporating oral history in her book."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 39);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Georgia Douglas Johnson’s 1922 poem “Benediction.”"}, {"type": "paragraph", "text": "Go forth, my son, / Winged by my heart’s desire! / Great reaches, yet unknown, / Await / For your possession. / I may not, if I would, / Retrace the way with you, / My pilgrimage is through, / But life is calling you!"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "To express hope that a child will have the same accomplishments as his parent did"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "To suggest that raising a child involves many struggles"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "To warn a child that he will face many challenges throughout his life"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "To encourage a child to embrace the experiences life will offer"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 40);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Edith Wharton’s 1905 novel The House of Mirth. Lily Bart and a companion are walking through a park."}, {"type": "paragraph", "text": "Lily had no real intimacy with nature, but she had a passion for the appropriate and could be keenly sensitive to a scene which was the fitting background of her own sensations. [[0|The landscape outspread below her seemed an enlargement of her present mood, and she found something of herself in its calmness, its breadth, its long free reaches]]. On the nearer slopes the sugar-maples wavered like pyres of light; lower down was a massing of grey orchards, and here and there the lingering green of an oak-grove."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It creates a detailed image of the physical setting of the scene."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It establishes that a character is experiencing an internal conflict."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It makes an assertion that the next sentence then expands on."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It illustrates an idea that is introduced in the previous sentence."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 41);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "[[0|Individual elephants and Arctic herbivores such as caribou tend to have fixed geographic ranges throughout their lifetimes]], which had prompted some researchers to speculate that the Arctic woolly mammoth, an extinct elephantid, might have exhibited similar behavior. Mammoth tusks grew in sequential layers, incorporating ingested minerals and organics, and so each ivory stratum reflects the ratio of strontium isotopes (87Sr/86Sr) in the local environment; thus, the sequence of strata shows where the animal roamed during life. Recent analysis of the strontium ratios in the strata of one Arctic woolly mammoth tusk in relation to the geographic distribution of strontium ratios in the environment shows the animal’s range begin to expand as it reached sexual maturity, only to contract again in its final 1.5 years."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It illustrates a pattern of behavior among certain animals in order to present a theory about exceptions to that pattern that is weakened by a finding described later in the text."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It describes a similarity in the behavior of certain animals in order to show why a method described later in the text did not reveal whether another animal also showed that behavior."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It introduces a trait shared by certain animals in order to contextualize a hypothesis about the origin of that trait that is advanced later in the text."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 42);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "In the 1960s, Gloria Richardson led a movement to promote racial equality. Her involvement in this effort was inspired by her daughter, Donna Richardson. In 1961, Donna joined protests organized by the Student Nonviolent Coordinating Committee in Cambridge, Maryland. Following her daughter, Gloria joined these protests too. Gloria soon became the cochair of the Cambridge Nonviolent Action Committee. She was also the leader of what became known as the Cambridge movement."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The Cambridge movement"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Her daughter Donna’s high school"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Protests to support environmental protections"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "A new business in Cambridge, Maryland"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 43);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Jane Austen’s 1811 novel Sense and Sensibility. Elinor lives with her younger sisters and her mother, Mrs. Dashwood."}, {"type": "paragraph", "text": "Elinor, this eldest daughter, whose advice was so effectual, possessed a strength of understanding, and coolness of judgment, which qualified her, though only nineteen, to be the counsellor of her mother, and enabled her frequently to counteract, to the advantage of them all, that eagerness of mind in Mrs. Dashwood which must generally have led to imprudence. She had an excellent heart;—her disposition was affectionate, and her feelings were strong; but she knew how to govern them: it was a knowledge which her mother had yet to learn; and which one of her sisters had resolved never to be taught."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Elinor often argues with her mother but fails to change her mind."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Elinor can be overly sensitive with regard to family matters."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Elinor thinks her mother is a bad role model."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Elinor is remarkably mature for her age."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 44);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Culinary anthropologist Vertamae Smart-Grosvenor may be known for her decades of work in national public television and radio, but her book Vibration Cooking: or, the Travel Notes of a Geechee Girl is likely her most influential project. The 1970 book, whose title refers to Smart-Grosvenor’s roots in the Low Country of South Carolina, was unusual for its time. It combined memoir, recipes, travel writing, and social commentary and challenged notions about conventions of food and cooking. Long admired by many, the book and its author have shaped contemporary approaches to writing about cuisine."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Smart-Grosvenor’s unconventional book Vibration Cooking: or, the Travel Notes of a Geechee Girl is an important contribution to food writing."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Smart-Grosvenor held many different positions over her life, including reporter and food writer."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Smart-Grosvenor’s groundbreaking book Vibration Cooking: or, the Travel Notes of a Geechee Girl didn’t receive the praise it deserved when it was first published in 1970."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Smart-Grosvenor was a talented chef whose work inspired many people to start cooking for themselves."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 45);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from Charles W. Chesnutt’s 1901 novel The Marrow of Tradition."}, {"type": "paragraph", "text": "Mrs. Ochiltree was a woman of strong individuality, whose comments upon her acquaintance[s], present or absent, were marked by a frankness at times no less than startling. This characteristic caused her to be more or less avoided. Mrs. Ochiltree was aware of this sentiment on the part of her acquaintance[s], and rather exulted in it."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "They try to refrain from discussing topics that would upset Mrs. Ochiltree."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "They are unable to spend as much time with Mrs. Ochiltree as she would like."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "They are too preoccupied with their own concerns to speak with Mrs. Ochiltree."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "They are likely offended by what Mrs. Ochiltree has said about them."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 46);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "“Mrs. Spring Fragrance” is a 1912 short story by Sui Sin Far. In the story, Mrs. Spring Fragrance, a Chinese immigrant living in Seattle, is traveling in California. In letters to her husband and friend, she demonstrates her concern for what’s happening at her home in Seattle while she is away: ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "“My honorable cousin is preparing for the Fifth Moon Festival, and wishes me to compound for the occasion some American ‘fudge,’ for which delectable sweet, made by my clumsy hands, you have sometimes shown a slight prejudice.”"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "“Next week I accompany Ah Oi to the beauteous town of San José. There will we be met by the son of the Illustrious Teacher.”"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "“Forget not to care for the cat, the birds, and the flowers. Do not eat too quickly nor fan too vigorously now that the weather is warming.”"}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "“I am enjoying a most agreeable visit, and American friends, as also our own, strive benevolently for the accomplishment of my pleasure.”"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 47);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "When digging for clams, their primary food, sea otters damage the roots of eelgrass plants growing on the seafloor. Near Vancouver Island in Canada, the otter population is large and well established, yet the eelgrass meadows are healthier than those found elsewhere off Canada’s coast. To explain this, conservation scientist Erin Foster and colleagues compared the Vancouver Island meadows to meadows where otters are absent or were reintroduced only recently. Finding that the Vancouver Island meadows have a more diverse gene pool than the others do, Foster hypothesized that damage to eelgrass roots increases the plant’s rate of sexual reproduction; this, in turn, boosts genetic diversity, which benefits the meadows’ health overall."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "At some sites in the study, eelgrass meadows are found near otter populations that are small and have only recently been reintroduced."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "At several sites not included in the study, there are large, well-established sea otter populations but no eelgrass meadows."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "At several sites not included in the study, eelgrass meadows’ health correlates negatively with the length of residence and size of otter populations."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "At some sites in the study, the health of plants unrelated to eelgrass correlates negatively with the length of residence and size of otter populations."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 48);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "In the twentieth century, ethnographers made a concerted effort to collect Mexican American folklore, but they did not always agree about that folklore’s origins. Scholars such as Aurelio Espinosa claimed that Mexican American folklore derived largely from the folklore of Spain, which ruled Mexico and what is now the southwestern United States from the sixteenth to early nineteenth centuries. Scholars such as Américo Paredes, by contrast, argued that while some Spanish influence is undeniable, Mexican American folklore is mainly the product of the ongoing interactions of various cultures in Mexico and the United States."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The folklore that the ethnographers collected included several songs written in the form of a décima, a type of poem originating in late sixteenth-century Spain."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Much of the folklore that the ethnographers collected had similar elements from region to region."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Most of the folklore that the ethnographers collected was previously unknown to scholars."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Most of the folklore that the ethnographers collected consisted of corridos—ballads about history and social life—of a clearly recent origin."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 49);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Among social animals that care for their young, such as chickens, macaque monkeys, and humans, newborns appear to show an innate attraction to faces and face-like stimuli. Elisabetta Versace and her colleagues used an image of three black dots arranged in the shape of eyes and a nose or mouth to test whether this trait also occurs in Testudo tortoises, which live alone and do not engage in parental care. They found that tortoise hatchlings showed a significant preference for the image, suggesting that ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "face-like stimuli are likely perceived as harmless by newborns of social species that practice parental care but as threatening by newborns of solitary species without parental care."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "researchers should not assume that an innate attraction to face-like stimuli is necessarily an adaptation related to social interaction or parental care."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "researchers can assume that the attraction to face-like stimuli that is seen in social species that practice parental care is learned rather than innate."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "newly hatched Testudo tortoises show a stronger preference for face-like stimuli than adult Testudo tortoises do."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 50);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Aptamers—synthetic DNA or RNA molecules that bind to target molecules—can be used to test for foodborne bacterial pathogens, though their specificity (the probability of returning a negative result in the absence of the focal pathogen) in real-world foods has been unclear. Sandeep Somvanshi et al. fabricated test paper incorporating aptamers targeting strain O157:H7 of the bacteria Escherichia coli; the paper shifts from pink to purple as the aptamers bind to target molecules. Somvanshi et al. tested the paper in store-bought pear juice they treated with E. coli O157:H7, other strains of E. coli, or other bacteria species. Following exposure, the paper from the O157:H7 test was purple while papers from the other tests were pink, suggesting that ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "aptamer-based tests in real-world foods are more likely to show a high degree of specificity if the focal pathogen is E. coli O157:H7 than if the focal pathogen is another strain of E. coli or another species."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "uncertainty about the specificity of aptamer-based tests for pathogens in real-world foods may be due to the similarity between E. coli O157:H7 and other E. coli strains."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "the specificity of the tests in a real-world food was unaffected by the aptamers’ tendency to bind to different strains of E. coli."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "the aptamers successfully bound to E. coli O157:H7 and the tests displayed a high degree of specificity in a real-world food."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 51);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "British scientists James Watson and Francis Crick won the Nobel Prize in part for their 1953 paper announcing the double helix structure of DNA, but it is misleading to say that Watson and Crick discovered the double helix. ______ findings were based on a famous X-ray image of DNA fibers, “Photo 51,” developed by X-ray crystallographer Rosalind Franklin and her graduate student Raymond Gosling."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "They’re"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It’s"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Their"}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Its"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 52);
