    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The Seikan Tunnel is a rail tunnel in Japan.", "It connects the island of Honshu to the island of Hokkaido.", "It is roughly 33 miles long.", "The Channel Tunnel is a rail tunnel in Europe.", "It connects Folkestone, England, to Coquelles, France.", "It is about 31 miles long."]}, {"type": "paragraph", "text": "The student wants to compare the lengths of the two rail tunnels."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Some of the world’s rail tunnels, including one tunnel that extends from Folkestone, England, to Coquelles, France, are longer than 30 miles."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The Seikan Tunnel is roughly 33 miles long, while the slightly shorter Channel Tunnel is about 31 miles long."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The Seikan Tunnel, which is roughly 33 miles long, connects the Japanese islands of Honshu and Hokkaido."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Both the Seikan Tunnel, which is located in Japan, and the Channel Tunnel, which is located in Europe, are examples of rail tunnels."}]}'::jsonb, false);
