    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Pinnipeds, which include seals, sea lions, and walruses, live in and around water.", "Pinnipeds are descended not from sea animals but from four-legged, land-dwelling carnivores.", "Canadian paleobiologist Natalia Rybczynski recently found a fossil with four legs, webbed toes, and the skull and teeth of a seal.", "Rybczynski refers to her rare find as a “transitional fossil.”", "The fossil illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors."]}, {"type": "paragraph", "text": "The student wants to emphasize the fossil’s significance."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Canadian paleobiologist Natalia Rybczynski’s fossil has the skull and teeth of a seal, which, like sea lions and walruses, is a pinniped."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Pinnipeds are descended from four-legged, land-dwelling carnivores; a fossil that resembles both was recently found."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Having four legs but the skull and teeth of a seal, the rare fossil illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "A “transitional fossil” was recently found by paleobiologist Natalia Rybczynski."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 63);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Physicist Muluneh Abebe was working on a garment suited for both warm and cold conditions.", "He analyzed the emissivity, or ability to emit heat, of the materials he planned to use.", "Abebe found that reflective metal fibers emitted almost no heat and had an emissivity of 0.02.", "He found that silicon carbide fibers absorbed large amounts of heat and had an emissivity of 0.74.", "The amount of heat a material absorbs is equal to the amount of heat it emits."]}, {"type": "paragraph", "text": "The student wants to contrast the emissivity of reflective metal fibers with that of silicon carbide fibers."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The ability of reflective metal fibers and silicon carbide fibers to emit heat was determined by an analysis of each material’s emissivity."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The amount of heat a material absorbs is equal to the amount it emits, as evidenced in Abebe’s analyses."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Though the reflective metal fibers and silicon carbide fibers had different rates of emissivity, Abebe planned to use both in a garment."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Whereas the reflective metal fibers had an emissivity of just 0.02, the silicon carbide fibers absorbed large amounts of heat, resulting in an emissivity of 0.74."}]}'::jsonb, true);
