    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In 2020, theater students at Radford and Virginia Tech chose an interactive, online format to present a play about woman suffrage activists.", "Their “Women and the Vote” website featured an interactive digital drawing of a Victorian-style house.", "Audiences were asked to focus on a room of their choice and select from that room an artifact related to the suffrage movement.", "One click took them to video clips, songs, artwork, and texts associated with the artifact.", "The play was popular with audiences because the format allowed them to control the experience."]}, {"type": "paragraph", "text": "The student wants to explain an advantage of the “Women and the Vote” format."}]}'::jsonb, 'source') returning id into v_stim;
