    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Ducklings expend up to 62.8% less energy when swimming in a line behind their mother than when swimming alone.", "The physics behind this energy savings hasn’t always been well understood.", "Naval architect Zhiming Yuan used computer simulations to study the effect of the mother duck’s wake.", "The study revealed that ducklings are pushed in a forward direction by the wake’s waves.", "Yuan determined this push reduces the effect of wave drag on the ducklings by 158%."]}, {"type": "paragraph", "text": "The student wants to present the study and its methodology."}]}'::jsonb, 'source') returning id into v_stim;
